CREATE POLICY "paper pdfs public read" ON storage.objects FOR SELECT USING (bucket_id = 'paper-pdfs');
CREATE POLICY "paper pdfs admin insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'paper-pdfs' AND has_role(auth.uid(), 'admin'::app_role));
CREATE POLICY "paper pdfs admin update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'paper-pdfs' AND has_role(auth.uid(), 'admin'::app_role));
CREATE POLICY "paper pdfs admin delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'paper-pdfs' AND has_role(auth.uid(), 'admin'::app_role));